from .coco_section_generic import YAMLBasedSectionGeneric


class SectionWs(YAMLBasedSectionGeneric):
    def __init__(self, section_name='WS'):
        super().__init__(section_name)

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        ws_section_content = {}
        ip_addr = epc_config['uesim_ip_configuration']['workstation_ip_addr']
        netmask = self._get_mask_from_ipv4_addr(epc_config['uesim_ip_configuration']['netmask'])
        ws_section_content['ip_addr'] = f'{ip_addr}/{netmask}'

        return ws_section_content

    @staticmethod
    def _get_mask_from_ipv4_addr(ipv4_addr):
        mask = 0

        for octet in ipv4_addr.split('.'):
            bin_octet = bin(int(octet))
            for bit in bin_octet[2:]:
                if bit == '1':
                    mask += 1
                else:
                    return mask
